function amAsset(id){return assetState.assets.find(x=>x.id===id)}
function amLive(r){return r?.status!=='void'}
function amValidDate(v){const m=amText(v).match(/^(1[34]\d{2})\/(0[1-9]|1[0-2])\/(0[1-9]|[12]\d|3[01])$/);if(!m)return false;return +m[3]<=(typeof jMonthLength==='function'?jMonthLength(+m[1],+m[2]):+m[2]<=6?31:30)}
function amDateInput(v){return amText(v).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/-/g,'/').replace(/^(\d{4})\/(\d)\//,'$1/0$2/').replace(/\/(\d)$/,'/0$1')}
// A count may only be recorded on or after the asset's latest live event; otherwise its system quantity would include later events.
function amLaterEvent(assetId,date){return assetState.quantityTransactions.find(x=>amLive(x)&&x.assetId===assetId&&String(x.date)>date)}
function amQuantityEffects(assetId,excludeId=''){return assetState.quantityTransactions.filter(x=>amLive(x)&&x.assetId===assetId&&x.id!==excludeId).reduce((s,x)=>s+amNum(x.effect),0)}
function amCurrentQuantity(assetOrId){const a=typeof assetOrId==='string'?amAsset(assetOrId):assetOrId;if(!a||a.trackingMode!=='quantity')return 0;return amNum(a.initialQuantity)+amQuantityEffects(a.id)}
function amProjectedQuantity(assetId,excludeTransactionId='',newEffect=0){const a=amAsset(assetId);if(!a||a.trackingMode!=='quantity')return 0;return amNum(a.initialQuantity)+amQuantityEffects(assetId,excludeTransactionId)+amNum(newEffect)}
function amSyncNextService(assetId){const a=amAsset(assetId);if(!a||a.trackingMode!=='numbered')return;const latest=assetState.maintenanceRecords.filter(r=>r.assetId===assetId&&r.nextServiceDate).sort((x,y)=>String(y.date).localeCompare(String(x.date)))[0];a.nextServiceDate=latest?.nextServiceDate||'';a.updatedAt=amNow()}
function amMaintenanceFor(assetId){return assetState.maintenanceRecords.filter(x=>x.assetId===assetId).sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function amTransactionsFor(assetId){return assetState.quantityTransactions.filter(x=>x.assetId===assetId).sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
