async function amApplyInitialMigration(raw){
  // Data-safety policy: never merge Seed or persist migrations during a normal Load.
  // Existing live API data is normalized only. Explicit Reset remains available from Settings.
  return amNormalize(raw);
}
const AssetStorage={
  async load(){return amApplyInitialMigration(await window.RAYO_API_GATEWAY.loadOrBootstrap('assets'))},
  async save(data){data.meta=data.meta||{};data.meta.updatedAt=amNow();data.meta.serverSaveToken=`ASSET-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;await window.RAYO_API_GATEWAY.saveModule('assets',data,{verify:window.RAYO_CONFIG?.verifyAfterSave!==false});return true}
};
// Data-safety: a failed Load never becomes an empty working copy; the page shows the error and offers a retry.
async function amEnsureLoaded(silent=false){if(assetLoaded||assetLoading||assetLoadError)return;assetLoading=true;try{assetState=await AssetStorage.load();assetLoaded=true;if(currentView==='assets')renderView()}catch(e){assetLoadError=String(e?.message||'خطا در بارگذاری اموال');if(!silent)toast(assetLoadError,true);if(currentView==='assets')renderView()}finally{assetLoading=false}}
