async function amDeleteAsset(id){const a=amAsset(id);if(!a)return;const linked=amMaintenanceFor(id).length+amTransactionsFor(id).length+amCountsFor(id).length+assetState.assetIncidents.filter(x=>x.assetId===id).length;if(linked){if(!confirm(`«${a.name}» سابقه ثبت‌شده دارد و حذف فیزیکی نمی‌شود. به آرشیو منتقل شود؟ سوابق آن حفظ می‌شوند.`))return;a.isArchived=true;a.archivedAt=amNow();a.updatedAt=amNow();if(await amCommit('آرشیو دارایی'))renderView();return}if(!confirm(`دارایی «${a.name}» حذف شود؟`))return;assetState.assets=assetState.assets.filter(x=>x.id!==id);assetState.maintenanceRecords=assetState.maintenanceRecords.filter(x=>x.assetId!==id);assetState.quantityTransactions=assetState.quantityTransactions.filter(x=>x.assetId!==id);assetState.counts=assetState.counts.filter(x=>x.assetId!==id);if(await amCommit('حذف دارایی'))renderView()}
